cat > $TMPDIR/modelcheck.py <<'EOF'
import json, math, sys
from math import gcd
import numpy as np
x=10**6
N=2*10**6
# spf sieve
spf=list(range(N+1))
for i in range(2,int(N**0.5)+1):
  if spf[i]==i:
    for j in range(i*i,N+1,i):
      if spf[j]==j: spf[j]=i
def fac(n):
  r={}
  while n>1:
    p=spf[n]; r[p]=r.get(p,0)+1; n//=p
  return r
primes=[p for p in range(2,N+1) if spf[p]==p]
c0=1.0
for p in primes: c0*=1-2/p**2
# beta for squarefree d up to D
D=int(x**0.5)*40+10
beta=[0.0]*(D+1); sqf=[]
for d in range(1,D+1):
  f=fac(d) if d<=N else None
  if any(v>1 for v in f.values()): continue
  b=c0
  for p in f: b/=(p*p-2)
  beta[d]=b; sqf.append(d)
six=6/math.pi**2
def model(q):
  fq=fac(q)
  sg=c0/q
  for p,v in fq.items(): sg*=1+p**min(2,v)/(p*p*(p*p-2))
  # tail-correct sum: product over primes not dividing q handled via c0 product? need full product
  return sg
# full Sigma g^2 = (c0/q) prod_p (1 + p^{min(2,v)}/(p^2(p^2-2))) over ALL p (v=0 gives 1/(p^2(p^2-2)))
P0=1.0
for p in primes: P0*=1+1/(p*p*(p*p-2))
def V_model(q):
  fq=fac(q)
  sg=c0/q*P0
  for p,v in fq.items(): sg*=(1+p**min(2,v)/(p*p*(p*p-2)))/(1+1/(p*p*(p*p-2)))
  tot=six*x - x*x*sg
  for d in sqf:
    g=gcd(d*d,q); Nd=q*d*d//g
    if d*d > x*q: break
    if Nd<=x:
      t=x/Nd; th=t-math.floor(t)
      tot+=beta[d]*(Nd*th*(1-th) - x + x*x/Nd)
  return tot
d=json.load(open('results.json'))
polys={'2k+1':(lambda t:2*t+1,lambda t:2),'k^2+1':(lambda t:t*t+1,lambda t:2*t)}
for name,(f,fp) in polys.items():
  rows=[r for r in d['polynomials'][name]['rows'] if r['x']==x]
  ys=sorted(r['y'] for r in rows)
  acc=0.0; k=1; res={}
  for y in ys:
    while k<=y:
      q=f(k)
      if q>=2: acc+=fp(k)*V_model(q)
      k+=1
    res[y]=acc
  for r in rows:
    print(name, r['target_ratio'], 'V=%.6e model=%.6e ratio=%.5f'%(r['V'],res[r['y']],r['V']/res[r['y']]))
EOF
